package com.sakti.banking.audit;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.*; import java.util.*;
@Document("audit_events") public class AuditEvent { @Id private String id; private String actor; private String action; private String target; private String outcome; private LocalDateTime createdAt=LocalDateTime.now(); private Map<String,Object> metadata=new LinkedHashMap<>(); public AuditEvent(){} public AuditEvent(String actor,String action,String target,String outcome){this.actor=actor;this.action=action;this.target=target;this.outcome=outcome;} public String getId(){return id;} public String getActor(){return actor;} public String getAction(){return action;} public String getTarget(){return target;} public String getOutcome(){return outcome;} public LocalDateTime getCreatedAt(){return createdAt;} public Map<String,Object> getMetadata(){return metadata;} }
